save('716236','а) x=π/2+2πn или x=-π/3+2πn или x=-2π/3+2πn; б) -14π/3,-13π/3,-7π/2',[
 ('а) Привести уравнение к квадратному относительно синуса','1-cos2x=2sin²x, sin(x-π)=-sin x. Получаем 2s²+(√3-2)s-√3=0, где s=sin x.',['trig'],['condition']),
 ('а) Разложить трёхчлен и решить простейшие уравнения','(s-1)(2s+√3)=0 ⇒ sin x=1 или sin x=-√3/2. Серии: π/2+2πn,-π/3+2πn,-2π/3+2πn, n∈Z.',['factor','trigeq'],['s1']),
 ('б) Отобрать все корни из [-5π;-7π/2]','В каждой серии подходит n=-2. Получаем -7π/2,-13π/3,-14π/3; других целых n нет.',['interval'],['condition','s2'])],
 [('trig','Преобразовывать тригонометрические выражения тождествами','Применять формулы приведения и двойного угла для сведения к одной тригонометрической функции.'),
 ('factor','Решать уравнение через нулевое произведение','Разложить выражение на множители и объединить допустимые корни каждого множителя.'),
 ('trigeq','Решать простейшее тригонометрическое уравнение','Записать все периодические серии решений sin x=c или cos x=c, проверив допустимость c.'),
 ('interval','Отбирать периодические корни на заданном промежутке','Определить целые параметры серий по границам промежутка и учесть включение концов.')],
 [('Свести к квадратному уравнению для синуса и отобрать корни',[1,2,3])])

